-- migrations ONLY: MJ core v6.2.1, then bizapps-common, -tasks, -accounting, -orders and -contracts
-- at their released `main`, then this app's migrations at `next`. Push result: 1 created,
-- 95 updated, 212 unchanged, 0 errors; the updates change no value and write no SQL, so the log
-- holds one statement.
--
-- CREATED: the Sales application setting HidePipelines (39E2F5E0-...), "false", which leaves
-- pipelines shown until an administrator sets it to "true". The application resolves by Name, and
-- the create is guarded on ID or (ApplicationID, Name), so a host that already has the setting keeps
-- its value. The push log's insert-or-update is cut to the insert for that reason: its update branch
-- would put "false" back over a host's "true" on every upgrade.
--
-- TRANSFORMS: `[__mj].` -> `[${mjSchema}].`; string values untouched. Idempotent.
-- =============================================================================================
-- Save MJ: Application Settings (core SP call only)
DECLARE @ID_a9e0d2665182 UNIQUEIDENTIFIER,
@ApplicationID_a9e0d2665182 UNIQUEIDENTIFIER,
@Name_a9e0d2665182 NVARCHAR(100),
@Value_a9e0d2665182 NVARCHAR(MAX),
@Comments_a9e0d2665182 NVARCHAR(MAX)
SET
  @ID_a9e0d2665182 = '39E2F5E0-6FA2-44AC-BCCA-568C062C27CB'
SET
  @Name_a9e0d2665182 = N'HidePipelines'
SET
  @Value_a9e0d2665182 = N'false'
SET
  @Comments_a9e0d2665182 = N'"true" runs every deal on its company''s default pipeline and hides pipelines across the Sales app: choosing a deal''s company chooses its pipeline, which the rep cannot change; the board and the stage card name companies instead of pipelines; and the Pipeline filter and column are gone. A company''s default pipeline is the first one linked to it: the pipeline marked IsDefault when it is linked, otherwise the lowest DisplayRank. "false" (the default) shows pipelines as before.'
SELECT TOP 1 @ApplicationID_a9e0d2665182 = [ID] FROM [${mjSchema}].[Application] WHERE [Name] = N'Sales' ORDER BY CASE WHEN [ID] = @ApplicationID_a9e0d2665182 THEN 0 ELSE 1 END
IF NOT EXISTS (SELECT 1 FROM [${mjSchema}].[ApplicationSetting]
               WHERE [ID] = @ID_a9e0d2665182
                  OR ([ApplicationID] = @ApplicationID_a9e0d2665182 AND [Name] = @Name_a9e0d2665182))
EXEC [${mjSchema}].spCreateApplicationSetting @ID = @ID_a9e0d2665182,
  @ApplicationID = @ApplicationID_a9e0d2665182,
  @Name = @Name_a9e0d2665182,
  @Value = @Value_a9e0d2665182,
  @Comments = @Comments_a9e0d2665182;

GO
